solution:
import json, re

class Ledger:
    def __init__(self):
        self.totals = {}
    def add(self, client, amount):
        self.totals[client] = round(self.totals.get(client, 0) + amount, 2)
    def save(self, path):
        with open(path, "w") as f:
            json.dump(self.totals, f, indent=2)
    @classmethod
    def load(cls, path):
        ledger = cls()
        with open(path) as f:
            ledger.totals = json.load(f)
        return ledger

ledger = Ledger()
rejected = 0
with open("invoices.txt") as f:
    for line in f:
        code, client, amount = line.strip().split(";")
        try:
            if not re.fullmatch(r"INV-\d{4}", code):
                raise ValueError("bad invoice code")
            ledger.add(client, float(amount))
        except ValueError:
            rejected += 1
            print("Rejected:", code)
ledger.save("ledger.json")
for client in sorted(ledger.totals):
    print(f"{client}: {ledger.totals[client]:.2f}")
print("Rejected lines:", rejected)
